+    describe("view_order_reversed", () => {
+        const opt = (value: boolean) => ({
+            value,
+            type: "bool",
+            default: false,
+            help: "",
+            choices: null,
+        });
+        const add = (st, id: string) =>
+            reduceFlows(
+                st,
+                flowActions.FLOWS_ADD({
+                    flow: { ...TFlow(), id },
+                    matching_filters: {},
+                }),
+            );
+        const ids = (st) => st.view.map((f) => f.id);
+
+        it("reads the option from OPTIONS_RECEIVE and OPTIONS_UPDATE", () => {
+            let st = reduceFlows(
+                state,
+                OPTIONS_RECEIVE({ view_order_reversed: opt(true) } as any),
+            );
+            expect(st.view_order_reversed).toBe(true);
+            st = reduceFlows(
+                st,
+                OPTIONS_UPDATE({ view_order_reversed: opt(false) } as any),
+            );
+            expect(st.view_order_reversed).toBe(false);
+        });
+        it("inserts new flows at the front when reversed", () => {
+            const st = reduceFlows(
+                state,
+                OPTIONS_UPDATE({ view_order_reversed: opt(true) } as any),
+            );
+            expect(ids(add(st, "5"))).toEqual(["5", "0", "1", "2", "3", "4"]);
+        });
+        it("appends new flows when not reversed", () => {
+            expect(ids(add(state, "5"))).toEqual([
+                "0",
+                "1",
+                "2",
+                "3",
+                "4",
+                "5",
+            ]);
+        });
+        it("prefers an active column sort", () => {
+            let st = reduceFlows(
+                state,
+                OPTIONS_UPDATE({ view_order_reversed: opt(true) } as any),
+            );
+            st = reduceFlows(
+                st,
+                flowActions.setSort({ column: "path", desc: false }),
+            );
+            st = add(st, "5");
+            expect(ids(st)).toEqual(
+                ids(
+                    reduceFlows(
+                        st,
+                        flowActions.setSort({ column: "path", desc: false }),
+                    ),
+                ),
+            );
+            expect(st._viewIndex.get("5")).toBe(st.view.length - 1);
+        });
+    });
 });

